@@ -35,0 +35,2 @@
+import java.awt.Toolkit;
+
@@ -40,0 +42,1 @@
+import java.util.concurrent.CompletableFuture;
@@ -106,0 +109,12 @@
+    private static boolean initAwt() {
+        // initialize AWT on a separate thread to avoid a possible deadlock
+        return CompletableFuture.supplyAsync(() -> {
+            try {
+                Toolkit.getDefaultToolkit();
+                return true;
+            } catch (Exception e) {
+                return false;
+            }
+        }).join();
+    }
+
@@ -545,0 +560,4 @@
+
+    private static void _initAwt() {
+
+    }

@@ -217,3 +217,1 @@
-    JNIEnv *env = jEnv;
-    jclass awt = [GlassHelper ClassForName:"java.awt.Toolkit" withEnv:env];
-    jmethodID method = (*env)->GetMethodID(env, awt, "getDefaultToolkit", "()V");
+    GET_MAIN_JENV;
@@ -221,3 +219,2 @@
-    if ((*env)->ExceptionCheck(env) == JNI_TRUE) {
-        return;
-    }
+    jboolean ok = (*env)->CallStaticBooleanMethod(env, [GlassHelper MacApplicationClass], [GlassHelper ApplicationInitAwt]);
+    GLASS_CHECK_EXCEPTION(env);
@@ -225,2 +222,3 @@
-    (*env)->CallVoidMethod(env, awt, method);
-    awtInitialized = true;
+    if (ok == JNI_TRUE) {
+        awtInitialized = true;
+    }

@@ -114,0 +114,20 @@
++ (jclass)MacApplicationClass
+{
+    static jclass _MacApplicationClass = NULL;
+    if (_MacApplicationClass == NULL)
+    {
+        GET_MAIN_JENV;
+        _MacApplicationClass =
+            [GlassHelper ClassForName:"com.sun.glass.ui.mac.MacApplication" withEnv:env];
+        if (_MacApplicationClass) {
+            _MacApplicationClass = (*env)->NewGlobalRef(env, _MacApplicationClass);
+        }
+        GLASS_CHECK_EXCEPTION(env);
+    }
+    if (_MacApplicationClass == NULL)
+    {
+        NSLog(@"GlassHelper error: _MacApplicationClass == NULL");
+    }
+    return _MacApplicationClass;
+}
+
@@ -306,0 +326,16 @@
++ (jmethodID)ApplicationInitAwt
+{
+    static jmethodID _ApplicationInitAwt = NULL;
+    if (_ApplicationInitAwt == NULL)
+    {
+        GET_MAIN_JENV;
+        _ApplicationInitAwt = (*env)->GetStaticMethodID(env, [GlassHelper MacApplicationClass], "initAwt", "()Z");
+        GLASS_CHECK_EXCEPTION(env);
+    }
+    if (_ApplicationInitAwt == NULL)
+    {
+        NSLog(@"GlassHelper error: _ApplicationInitAwt == NULL");
+    }
+    return _ApplicationInitAwt;
+}
